INSERT INTO `his_config_info` VALUES (2, 1, 'huimao-gateway-dev.yml', 'DEFAULT_GROUP', '', 'spring:\n  redis:\n    host: huimao-redis\n    port: 6379\n#    password:\n    timeout: 1000 # 连接超时时间（毫秒）\n    jedis:\n      pool:\n        max-active: 10 # 连接池最大连接数（使用负值表示没有限制）\n        max-wait: -1ms # 连接池最大阻塞等待时间（使用负值表示没有限制）\n        max-idle: 8 # 连接池中的最大  空闲连接\n        min-idle: 0 # 连接池中的最小空闲连接\n  cloud:\n    gateway:\n      discovery:\n        locator:\n          lowerCaseServiceId: true\n          enabled: true\n      routes:\n        # 认证中心\n        - id: huimao-auth\n          uri: lb://huimao-auth\n          predicates:\n            - Path=/auth/**\n          filters:\n            # 验证码处理\n            - CacheRequestFilter\n            - ValidateCodeFilter\n            - StripPrefix=1\n        # 代码生成\n        - id: huimao-gen\n          uri: lb://huimao-gen\n          predicates:\n            - Path=/code/**\n          filters:\n            - StripPrefix=1\n        # 系统模块\n        - id: huimao-system\n          uri: lb://huimao-system\n          predicates:\n            - Path=/system/**\n          filters:\n            - StripPrefix=1\n        # 文件服务\n        - id: huimao-file\n          uri: lb://huimao-file\n          predicates:\n            - Path=/file/**\n          filters:\n            - StripPrefix=1\n        # 监控模块\n        - id: huimao-monitor\n          uri: lb://huimao-monitor\n          predicates:\n            - Path=/monitor/**\n          filters:\n            - StripPrefix=1\n        # 定时模块\n        - id: huimao-job\n          uri: lb://huimao-job\n          predicates:\n            - Path=/job/**\n          filters:\n            - StripPrefix=1\n        # 样例模块\n        - id: huimao-demo\n          uri: lb://huimao-demo\n          predicates:\n            - Path=/demo/**\n          filters:\n            - StripPrefix=1\n\n# 安全配置\nsecurity:\n  # 验证码\n  captcha:\n    enabled: true\n    type: math\n  # 防止XSS攻击\n  xss:\n    enabled: true\n    excludeUrls:\n      - /system/notice\n  # 不校验白名单\n  ignore:\n    whites:\n      - /auth/logout\n      - /auth/login\n      - /auth/register\n      - /*/v2/api-docs\n      - /csrf\n      - /job/api/callback\n      - /job/api/registry\n      - /job/api/registryRemove\n      - /file/documents/**', '9086f1a716b3d32361749ca9814592af', '2026-04-23 13:43:17', '2026-04-23 13:43:17', 'nacos', '127.0.0.1', 'U', '', '');
INSERT INTO `his_config_info` VALUES (3, 2, 'huimao-auth-dev.yml', 'DEFAULT_GROUP', '', 'spring: \n  redis:\n    host: huimao-redis\n    port: 6379\n#    password:\n    timeout: 1000 # 连接超时时间（毫秒）\n    jedis:\n      pool:\n        max-active: 10 # 连接池最大连接数（使用负值表示没有限制）\n        max-wait: -1ms # 连接池最大阻塞等待时间（使用负值表示没有限制）\n        max-idle: 8 # 连接池中的最大  空闲连接\n        min-idle: 0 # 连接池中的最小空闲连接\nfeign:\n  sentinel:\n    enabled: true\n  okhttp:\n    enabled: true\n  httpclient:\n    enabled: false\n  client:\n    config:\n      default:\n        connectTimeout: 10000\n        readTimeout: 10000\n        #loggerLevel: full\n        requestInterceptors: com.huimao.common.security.feign.FeignRequestInterceptor', '6bdf6a7cb1cb274b035a786772211120', '2026-04-23 13:43:29', '2026-04-23 13:43:30', 'nacos', '127.0.0.1', 'U', '', '');
INSERT INTO `his_config_info` VALUES (4, 3, 'huimao-monitor-dev.yml', 'DEFAULT_GROUP', '', '# spring配置\nspring: \n  redis:\n    host: huimao-redis\n    port: 6379\n#    password:\n    timeout: 1000 # 连接超时时间（毫秒）\n    # jedis:\n    #   pool:\n    #     max-active: 10 # 连接池最大连接数（使用负值表示没有限制）\n    #     max-wait: -1ms # 连接池最大阻塞等待时间（使用负值表示没有限制）\n    #     max-idle: 8 # 连接池中的最大  空闲连接\n    #     min-idle: 0 # 连接池中的最小空闲连接\n    lettuce:\n      pool:\n        max-active: 20\n        max-wait: 500ms\n        max-idle: 10\n        min-idle: 2\n  datasource: \n    driver-class-name: com.mysql.cj.jdbc.Driver\n    url: jdbc:mysql://huimao-mysql:3306/huimao_platform?useUnicode=true&characterEncoding=utf8&zeroDateTimeBehavior=convertToNull&useSSL=true&serverTimezone=GMT%2B8\n    username: root\n    password: \n# swagger配置\nswagger:\n  title: 代码生成接口文档\n  license: Powered By huimao\n  licenseUrl: https://huimao.cn\n# seata配置\nseata:\n  # 默认关闭，如需启用spring.datasource.dynami.seata需要同时开启\n  enabled: false\n  # Seata 应用编号，默认为 ${spring.application.name}\n  application-id: ${spring.application.name}\n  # Seata 事务组编号，用于 TC 集群名\n  tx-service-group: ${spring.application.name}-group\n  # 关闭自动代理\n  enable-auto-data-source-proxy: false\n  # 服务配置项\n  service:\n    # 虚拟组和分组的映射\n    vgroup-mapping:\n      huimao-system-group: default\n  config:\n    type: nacos\n    nacos:\n      serverAddr: huimao-nacos:8848\n      group: SEATA_GROUP\n      namespace:\n  registry:\n    type: nacos\n    nacos:\n      application: seata-server\n      server-addr: huimao-nacos:8848\n      namespace:', 'af2727a14e577dbd907a715fcef22a9a', '2026-04-23 13:44:03', '2026-04-23 13:44:04', 'nacos', '127.0.0.1', 'U', '', '');
INSERT INTO `his_config_info` VALUES (5, 4, 'huimao-system-dev.yml', 'DEFAULT_GROUP', '', '# spring配置\r\nspring:\r\n  redis:\r\n    host: huimao-redis\r\n    port: 6379\r\n#    password:\r\n    timeout: 1000 # 连接超时时间（毫秒）\r\n    jedis:\r\n      pool:\r\n        max-active: 10 # 连接池最大连接数（使用负值表示没有限制）\r\n        max-wait: -1ms # 连接池最大阻塞等待时间（使用负值表示没有限制）\r\n        max-idle: 8 # 连接池中的最大  空闲连接\r\n        min-idle: 0 # 连接池中的最小空闲连接\r\n  datasource:\r\n    druid:\r\n      stat-view-servlet:\r\n        enabled: true\r\n        loginUsername: admin\r\n        loginPassword: 123456\r\n    dynamic:\r\n      druid:\r\n        initial-size: 5\r\n        min-idle: 50\r\n        maxActive: 100\r\n        maxWait: 60000\r\n        timeBetweenEvictionRunsMillis: 300000\r\n        minEvictableIdleTimeMillis: 300000\r\n        validationQuery: SELECT 1 FROM DUAL\r\n        testWhileIdle: true\r\n        testOnBorrow: false\r\n        testOnReturn: false\r\n        poolPreparedStatements: true\r\n        maxPoolPreparedStatementPerConnectionSize: 50\r\n        filters: stat,slf4j\r\n        connectionProperties: druid.stat.mergeSql=true;druid.stat.slowSqlMillis=500\r\n      datasource:\r\n          # 主库数据源\r\n          master:\r\n            driver-class-name: com.mysql.cj.jdbc.Driver\r\n            url: jdbc:mysql://huimao-mysql:3306/huimao_platform?useUnicode=true&characterEncoding=utf8&zeroDateTimeBehavior=convertToNull&useSSL=true&serverTimezone=GMT%2B8\r\n            username: root\r\n            password: 123456\r\nseata:\r\n  # 默认关闭，如需启用spring.datasource.dynami.seata需要同时开启\r\n  enabled: false\r\n  # Seata 应用编号，默认为 ${spring.application.name}\r\n  application-id: ${spring.application.name}\r\n  # Seata 事务组编号，用于 TC 集群名\r\n  tx-service-group: ${spring.application.name}-group\r\n  # 关闭自动代理\r\n  enable-auto-data-source-proxy: false\r\n  # 服务配置项\r\n  service:\r\n    # 虚拟组和分组的映射\r\n    vgroup-mapping:\r\n      huimao-system-group: default\r\n  config:\r\n    type: nacos\r\n    nacos:\r\n      serverAddr: huimao-nacos:8848\r\n      group: SEATA_GROUP\r\n      namespace:\r\n  registry:\r\n    type: nacos\r\n    nacos:\r\n      application: seata-server\r\n      server-addr: huimao-nacos:8848\r\n      namespace:\r\n\r\n# mybatis配置\r\n# mybatis:\r\n#     搜索指定包别名\r\n#     typeAliasesPackage: com.huimao.system\r\n#     配置mapper的扫描，找到所有的mapper.xml映射文件\r\n#     mapperLocations: classpath:mapper/**/*.xml\r\n\r\n# swagger配置\r\nswagger:\r\n  title: 系统模块接口文档\r\n  license: Powered By huimao\r\n  licenseUrl: https://huimao.vip\r\nfeign:\r\n  sentinel:\r\n    enabled: true\r\n  okhttp:\r\n    enabled: true\r\n  httpclient:\r\n    enabled: false\r\n  client:\r\n    config:\r\n      default:\r\n        connectTimeout: 10000\r\n        readTimeout: 10000\r\n        loggerLevel: full\r\n        requestInterceptors: com.huimao.common.security.feign.FeignRequestInterceptor\r\n', '2739602abe1b95f0f48d5d6e7ae2ed61', '2026-04-23 13:44:32', '2026-04-23 13:44:32', 'nacos', '127.0.0.1', 'U', '', '');
INSERT INTO `his_config_info` VALUES (6, 5, 'huimao-gen-dev.yml', 'DEFAULT_GROUP', '', '# spring配置\r\nspring: \r\n  redis:\r\n    host: huimao-redis\r\n    port: 6379\r\n    #password: \r\n    timeout: 1000 # 连接超时时间（毫秒）\r\n    jedis:\r\n      pool:\r\n        max-active: 10 # 连接池最大连接数（使用负值表示没有限制）\r\n        max-wait: -1ms # 连接池最大阻塞等待时间（使用负值表示没有限制）\r\n        max-idle: 8 # 连接池中的最大  空闲连接\r\n        min-idle: 0 # 连接池中的最小空闲连接\r\n  datasource: \r\n    driver-class-name: com.mysql.cj.jdbc.Driver\r\n    url: jdbc:mysql://huimao-mysql:3306/huimao_platform?useUnicode=true&characterEncoding=utf8&zeroDateTimeBehavior=convertToNull&useSSL=true&serverTimezone=GMT%2B8\r\n    username: root\r\n    password: 123456\r\n# swagger配置\r\nswagger:\r\n  title: 代码生成接口文档\r\n  license: Powered By huimao\r\n  licenseUrl: https://huimao.cn\r\n\r\n# 代码生成\r\ngen: \r\n  # 作者\r\n  author: huimao\r\n  # 默认生成包路径 system 需改成自己的模块名称 如 system monitor tool\r\n  packageName: com.huimao.system\r\n  # 自动去除表前缀，默认是false\r\n  autoRemovePre: false\r\n  # 表前缀（生成类名不会包含表前缀，多个用逗号分隔）\r\n  tablePrefix: sys_\r\n', 'c642441d1d5e8fe234a16f2127efb714', '2026-04-23 13:44:51', '2026-04-23 13:44:52', 'nacos', '127.0.0.1', 'U', '', '');
INSERT INTO `his_config_info` VALUES (9, 6, 'huimao-demo-dev.yml', 'DEFAULT_GROUP', '', '# spring配置\r\nspring: \r\n  redis:\r\n    host: huimao-redis\r\n    port: 6379\r\n    #password: \r\n    timeout: 1000 # 连接超时时间（毫秒）\r\n    jedis:\r\n      pool:\r\n        max-active: 10 # 连接池最大连接数（使用负值表示没有限制）\r\n        max-wait: -1ms # 连接池最大阻塞等待时间（使用负值表示没有限制）\r\n        max-idle: 8 # 连接池中的最大  空闲连接\r\n        min-idle: 0 # 连接池中的最小空闲连接\r\n  datasource: \r\n    driver-class-name: com.mysql.cj.jdbc.Driver\r\n    url: jdbc:mysql://huimao-mysql:3306/huimao_platform?useUnicode=true&characterEncoding=utf8&zeroDateTimeBehavior=convertToNull&useSSL=true&serverTimezone=GMT%2B8\r\n    username: root\r\n    password: 123456\r\n# swagger配置\r\nswagger:\r\n  title: 代码生成接口文档\r\n  license: Powered By huimao\r\n  licenseUrl: https://huimao.cn\r\n\r\nxxl:\r\n  job:\r\n    admin:\r\n      ### xxl-job admin address list, such as \"http://address\" or \"http://address01,http://address02\"\r\n      addresses: http://localhost/dev-api/job\r\n    ### xxl-job, access token\r\n    accessToken: default_token\r\n    executor: \r\n      ### xxl-job executor appname\r\n      appname: xxl-job-executor-sample\r\n      ### xxl-job executor registry-address: default use address to registry , otherwise use ip:port if address is null\r\n      address: \r\n      ### xxl-job executor server-info\r\n      ip: 127.0.0.1\r\n      port: 9999\r\n      ### xxl-job executor log-path\r\n      logpath: ./logs/xxl-job\r\n      ### xxl-job executor log-retention-days\r\n      logretentiondays: 30', '327d392223348f66ec20630329485a75', '2026-04-23 13:45:21', '2026-04-23 13:45:22', 'nacos', '127.0.0.1', 'U', '', '');
INSERT INTO `his_config_info` VALUES (10, 7, 'huimao-job-dev.yml', 'DEFAULT_GROUP', '', '# spring配置\r\nspring: \r\n  redis:\r\n    host: huimao-redis\r\n    port: 6379\r\n    #password: \r\n    timeout: 1000 # 连接超时时间（毫秒）\r\n    jedis:\r\n      pool:\r\n        max-active: 10 # 连接池最大连接数（使用负值表示没有限制）\r\n        max-wait: -1ms # 连接池最大阻塞等待时间（使用负值表示没有限制）\r\n        max-idle: 8 # 连接池中的最大  空闲连接\r\n        min-idle: 0 # 连接池中的最小空闲连接\r\n  datasource: \r\n    driver-class-name: com.mysql.cj.jdbc.Driver\r\n    url: jdbc:mysql://huimao-mysql:3306/huimao_platform?useUnicode=true&characterEncoding=utf8&zeroDateTimeBehavior=convertToNull&useSSL=true&serverTimezone=GMT%2B8\r\n    username: root\r\n    password: 123456\r\n  mail:\r\n    host: www.163.com\r\n    port: 25\r\n    username: xxxxxx@163.com\r\n    from: xxxxxx@163.com\r\n    password: xxxxxx\r\n    properties: \r\n      mail: \r\n        smtp: \r\n          auth: false\r\n          starttls: \r\n            enable: false\r\n            required: false\r\n          socketFactory: \r\n            class: javax.net.ssl.SSLSocketFactory\r\n          \r\n# swagger配置\r\nswagger:\r\n  title: 定时任务接口文档\r\n  license: Powered By huimao\r\n  licenseUrl: https://huimao.cn\r\n\r\nxxl:\r\n  job:\r\n    accessToken: default_token\r\n    i18n: zh_CN\r\n    logretentiondays: 30\r\n    triggerpool: \r\n      fast: \r\n        max: 200\r\n      slow: \r\n        max: 100\r\n\r\ncustom:\r\n  log:\r\n    list:\r\n      - scheduleJobQuery-error\r\n      - findFailJobLogIds-error\r\n      - findByAddressType-error\r\n\r\n\r\n', '9a4c75ad8207809b45c46da2ade06ab3', '2026-04-23 13:45:46', '2026-04-23 13:45:47', 'nacos', '127.0.0.1', 'U', '', '10');
INSERT INTO `his_config_info` VALUES (0, 8, 'huimao-parking-dev.yml', 'DEFAULT_GROUP', '', '# spring配置\r\nspring:\r\n  redis:\r\n    host: 127.0.0.1\r\n    port: 6379\r\n    password: aq114477\r\n    timeout: 1000\r\n    jedis:\r\n      pool:\r\n        max-active: 10\r\n        max-wait: -1ms\r\n        max-idle: 8\r\n        min-idle: 0\r\n  datasource:\r\n    druid:\r\n      stat-view-servlet:\r\n        enabled: true\r\n        loginUsername: admin\r\n        loginPassword: 123456\r\n    dynamic:\r\n      druid:\r\n        initial-size: 5\r\n        min-idle: 50\r\n        maxActive: 100\r\n        maxWait: 60000\r\n        timeBetweenEvictionRunsMillis: 300000\r\n        minEvictableIdleTimeMillis: 300000\r\n        validationQuery: SELECT 1 FROM DUAL\r\n        testWhileIdle: true\r\n        testOnBorrow: false\r\n        testOnReturn: false\r\n        poolPreparedStatements: true\r\n        maxPoolPreparedStatementPerConnectionSize: 50\r\n        filters: stat,slf4j\r\n        connectionProperties: druid.stat.mergeSql=true;druid.stat.slowSqlMillis=500\r\n      datasource:\r\n        master:\r\n          driver-class-name: com.mysql.cj.jdbc.Driver\r\n          url: jdbc:mysql://127.0.0.1:3306/huimao_platform?useUnicode=true&characterEncoding=utf8&zeroDateTimeBehavior=convertToNull&useSSL=true&serverTimezone=GMT%2B8\r\n          username: root\r\n          password: aq114477\r\n\r\nseata:\r\n  enabled: false\r\n  application-id: ${spring.application.name}\r\n  tx-service-group: ${spring.application.name}-group\r\n  enable-auto-data-source-proxy: false\r\n  service:\r\n    vgroup-mapping:\r\n      huimao-parking-group: default\r\n  config:\r\n    type: nacos\r\n    nacos:\r\n      serverAddr: huimao-nacos:8848\r\n      group: SEATA_GROUP\r\n      namespace:\r\n  registry:\r\n    type: nacos\r\n    nacos:\r\n      application: seata-server\r\n      server-addr: huimao-nacos:8848\r\n      namespace:\r\n\r\nswagger:\r\n  title: 停车场模块接口文档\r\n  license: Powered By huimao\r\n  licenseUrl: https://huimao.vip\r\n\r\nfeign:\r\n  sentinel:\r\n    enabled: true\r\n  okhttp:\r\n    enabled: true\r\n  httpclient:\r\n    enabled: false\r\n  client:\r\n    config:\r\n      default:\r\n        connectTimeout: 10000\r\n        readTimeout: 10000\r\n        loggerLevel: full\r\n        requestInterceptors: com.huimao.common.security.feign.FeignRequestInterceptor\r\n\r\nhuimao:\r\n  tenant:\r\n    ignore-tables:\r\n      - sys_config\r\n      - gen_table\r\n      - gen_table_column\r\n      - sys_dict_data\r\n      - sys_dict_type\r\n      - sys_menu\r\n      - sys_tenant\r\n      - sys_tenant_package\r\n      - sys_oper_log\r\n      - sys_logininfor\r\n      - branch_table\r\n      - global_table\r\n      - lock_table\r\n      - undo_log\r\n      - xxl_job_group\r\n      - xxl_job_info\r\n      - xxl_job_lock\r\n      - xxl_job_log\r\n      - xxl_job_log_report\r\n      - xxl_job_logglue\r\n      - xxl_job_registry\r\n      - xxl_job_user\r\n      - parking_lot\r\n      - parking_gate\r\n      - parking_device\r\n      - parking_charge_rule\r\n      - parking_charge_rule_period\r\n      - parking_tenant_settle_config\r\n      - parking_session\r\n      - parking_order\r\n      - parking_payment\r\n      - parking_io_event\r\n      - parking_gate_command\r\n      - parking_account\r\n      - parking_account_flow\r\n      - parking_withdraw_order\r\n      - parking_daily_stat\r\n', '37eae101f163b4eae42c1e156b94aa39', '2026-04-23 14:13:16', '2026-04-23 14:13:16', NULL, '127.0.0.1', 'I', '', '');
INSERT INTO `his_config_info` VALUES (2, 9, 'huimao-gateway-dev.yml', 'DEFAULT_GROUP', '', 'spring:\n  redis:\n    host: 127.0.0.1\n    port: 6379\n    password: aq114477\n    timeout: 1000 # 连接超时时间（毫秒）\n    jedis:\n      pool:\n        max-active: 10 # 连接池最大连接数（使用负值表示没有限制）\n        max-wait: -1ms # 连接池最大阻塞等待时间（使用负值表示没有限制）\n        max-idle: 8 # 连接池中的最大  空闲连接\n        min-idle: 0 # 连接池中的最小空闲连接\n  cloud:\n    gateway:\n      discovery:\n        locator:\n          lowerCaseServiceId: true\n          enabled: true\n      routes:\n        # 认证中心\n        - id: huimao-auth\n          uri: lb://huimao-auth\n          predicates:\n            - Path=/auth/**\n          filters:\n            # 验证码处理\n            - CacheRequestFilter\n            - ValidateCodeFilter\n            - StripPrefix=1\n        # 代码生成\n        - id: huimao-gen\n          uri: lb://huimao-gen\n          predicates:\n            - Path=/code/**\n          filters:\n            - StripPrefix=1\n        # 系统模块\n        - id: huimao-system\n          uri: lb://huimao-system\n          predicates:\n            - Path=/system/**\n          filters:\n            - StripPrefix=1\n        # 文件服务\n        - id: huimao-file\n          uri: lb://huimao-file\n          predicates:\n            - Path=/file/**\n          filters:\n            - StripPrefix=1\n        # 监控模块\n        - id: huimao-monitor\n          uri: lb://huimao-monitor\n          predicates:\n            - Path=/monitor/**\n          filters:\n            - StripPrefix=1\n        # 定时模块\n        - id: huimao-job\n          uri: lb://huimao-job\n          predicates:\n            - Path=/job/**\n          filters:\n            - StripPrefix=1\n        # 样例模块\n        - id: huimao-demo\n          uri: lb://huimao-demo\n          predicates:\n            - Path=/demo/**\n          filters:\n            - StripPrefix=1\n\n# 安全配置\nsecurity:\n  # 验证码\n  captcha:\n    enabled: true\n    type: math\n  # 防止XSS攻击\n  xss:\n    enabled: true\n    excludeUrls:\n      - /system/notice\n  # 不校验白名单\n  ignore:\n    whites:\n      - /auth/logout\n      - /auth/login\n      - /auth/register\n      - /*/v2/api-docs\n      - /csrf\n      - /job/api/callback\n      - /job/api/registry\n      - /job/api/registryRemove\n      - /file/documents/**', '9bce3e31f4957f7e0f125fcccac947af', '2026-04-23 14:16:14', '2026-04-23 14:16:14', 'nacos', '127.0.0.1', 'U', '', '');
INSERT INTO `his_config_info` VALUES (1, 10, 'application-dev.yml', 'DEFAULT_GROUP', '', 'spring:\r\n  autoconfigure:\r\n    exclude: com.alibaba.druid.spring.boot.autoconfigure.DruidDataSourceAutoConfigure\r\n  mvc:\r\n    pathmatch:\r\n      matching-strategy: ant_path_matcher\r\n# mail配置\r\n  mail:\r\n    # 配置 SMTP 服务器地址\r\n    host: smtpdm.aliyun.com\r\n    # 发送者邮箱\r\n    username: xxxxxx@163.com\r\n    # 配置密码，注意不是真正的密码，而是刚刚申请到的授权码\r\n    password: xxxxx\r\n    # 端口号465或587\r\n    port: 465\r\n    # 默认的邮件编码为UTF-8\r\n    default-encoding: UTF-8\r\n    # 配置SSL 加密工厂\r\n    properties:\r\n      mail:\r\n        smtp:\r\n          ssl:\r\n            enable: true\r\n          socketFactoryClass: javax.net.ssl.SSLSocketFactory\r\n        #表示开启 DEBUG 模式，这样，邮件发送过程的日志会在控制台打印出来，方便排查错误\r\n        debug: true\r\n# feign 配置\r\nfeign:\r\n  sentinel:\r\n    enabled: true\r\n  okhttp:\r\n    enabled: true\r\n  httpclient:\r\n    enabled: false\r\n  client:\r\n    config:\r\n      default:\r\n        connectTimeout: 10000\r\n        readTimeout: 10000\r\n      huimao-job:\r\n        connectTimeout: 100000\r\n        readTimeout: 100000\r\n  compression:\r\n    request:\r\n      enabled: true\r\n    response:\r\n      enabled: true\r\n\r\n# 暴露监控端点\r\nmanagement:\r\n  endpoints:\r\n    web:\r\n      exposure:\r\n        include: \'*\'\r\nlogging:\r\n  level:\r\n    org.springframework: info\r\n    com.huimao: debug\r\n  #log日志文件配置\r\n  file_basePath: ./logs\r\n  file_prefix: ${spring.application.name}\r\nmybatis-plus:\r\n  mapper-locations: classpath*:mapper/**/*.xml\r\n  global-config:\r\n    banner: false\r\n    refresh-mapper: true\r\n    db-config:\r\n      id-type: auto\r\n      table-underline: true\r\n      logic-delete-value: 1\r\n      logic-not-delete-value: 0\r\n  configuration:\r\n    map-underscore-to-camel-case: true\r\n  type-handlers-package: com.huimao.common.mybatisplus\r\nhuimao:\r\n  #多租户配置\r\n  tenant:\r\n    ignore-tables:\r\n      #系统表\r\n      - sys_config\r\n      - gen_table\r\n      - gen_table_column\r\n      - sys_dict_data\r\n      - sys_dict_type\r\n      - sys_menu\r\n      - sys_tenant\r\n      - sys_tenant_package\r\n      - sys_oper_log\r\n      - sys_logininfor\r\n      - branch_table\r\n      - global_table\r\n      - lock_table\r\n      - undo_log\r\n      - xxl_job_group\r\n      - xxl_job_info\r\n      - xxl_job_lock\r\n      - xxl_job_log\r\n      - xxl_job_log_report\r\n      - xxl_job_logglue\r\n      - xxl_job_registry\r\n      - xxl_job_user\r\n      #自定义表\r\n# 短信服务\r\naliyun:\r\n  endpoint: cn-shanghai\r\n  accessKeyId:  \r\n  accessKeySecret: \r\n  signName:  \r\n  templateCode: \r\n# 本地文件上传    \r\nfile:\r\n  domain: http://127.0.0.1:39300\r\n  path: /home/upload\r\n  prefix: /documents\r\n', '4b7ecbd1f14068c9fc5f1293ce044653', '2026-04-23 14:16:55', '2026-04-23 14:16:56', 'nacos', '127.0.0.1', 'U', '', '');
INSERT INTO `his_config_info` VALUES (0, 11, 'huimao-parking-simulator-dev.yml', 'DEFAULT_GROUP', '', '# spring配置\r\nspring:\r\n  autoconfigure:\r\n    exclude: com.alibaba.druid.spring.boot.autoconfigure.DruidDataSourceAutoConfigure\r\n  mvc:\r\n    pathmatch:\r\n      matching-strategy: ant_path_matcher\r\n  redis:\r\n    host: 127.0.0.1\r\n    port: 6379\r\n    password: aq114477\r\n    timeout: 1000\r\n    jedis:\r\n      pool:\r\n        max-active: 10\r\n        max-wait: -1ms\r\n        max-idle: 8\r\n        min-idle: 0\r\n  datasource:\r\n    druid:\r\n      stat-view-servlet:\r\n        enabled: true\r\n        loginUsername: admin\r\n        loginPassword: 123456\r\n    dynamic:\r\n      druid:\r\n        initial-size: 5\r\n        min-idle: 10\r\n        maxActive: 50\r\n        maxWait: 60000\r\n        timeBetweenEvictionRunsMillis: 300000\r\n        minEvictableIdleTimeMillis: 300000\r\n        validationQuery: SELECT 1 FROM DUAL\r\n        testWhileIdle: true\r\n        testOnBorrow: false\r\n        testOnReturn: false\r\n        poolPreparedStatements: true\r\n        maxPoolPreparedStatementPerConnectionSize: 20\r\n        filters: stat,slf4j\r\n        connectionProperties: druid.stat.mergeSql=true;druid.stat.slowSqlMillis=500\r\n      datasource:\r\n        master:\r\n          driver-class-name: com.mysql.cj.jdbc.Driver\r\n          url: jdbc:mysql://127.0.0.1:3306/huimao_platform?useUnicode=true&characterEncoding=utf8&zeroDateTimeBehavior=convertToNull&useSSL=true&serverTimezone=GMT%2B8\r\n          username: root\r\n          password: aq114477\r\n\r\nseata:\r\n  enabled: false\r\n  application-id: ${spring.application.name}\r\n  tx-service-group: ${spring.application.name}-group\r\n  enable-auto-data-source-proxy: false\r\n  service:\r\n    vgroup-mapping:\r\n      huimao-system-group: default\r\n  config:\r\n    type: nacos\r\n    nacos:\r\n      serverAddr: huimao-nacos:8848\r\n      group: SEATA_GROUP\r\n      namespace:\r\n  registry:\r\n    type: nacos\r\n    nacos:\r\n      application: seata-server\r\n      server-addr: huimao-nacos:8848\r\n      namespace:\r\n\r\nswagger:\r\n  title: 停车设备模拟器接口文档\r\n  license: Powered By huimao\r\n  licenseUrl: https://huimao.vip\r\n\r\nfeign:\r\n  sentinel:\r\n    enabled: true\r\n  okhttp:\r\n    enabled: true\r\n  httpclient:\r\n    enabled: false\r\n  client:\r\n    config:\r\n      default:\r\n        connectTimeout: 10000\r\n        readTimeout: 10000\r\n        loggerLevel: full\r\n        requestInterceptors: com.huimao.common.security.feign.FeignRequestInterceptor\r\n  compression:\r\n    request:\r\n      enabled: true\r\n    response:\r\n      enabled: true\r\n\r\nmanagement:\r\n  endpoints:\r\n    web:\r\n      exposure:\r\n        include: \'*\'\r\n\r\nlogging:\r\n  level:\r\n    org.springframework: info\r\n    com.huimao: debug\r\n  file_basePath: ./logs\r\n  file_prefix: ${spring.application.name}\r\n\r\nmybatis-plus:\r\n  mapper-locations: classpath*:mapper/**/*.xml\r\n  global-config:\r\n    banner: false\r\n    refresh-mapper: true\r\n    db-config:\r\n      id-type: auto\r\n      table-underline: true\r\n      logic-delete-value: 1\r\n      logic-not-delete-value: 0\r\n  configuration:\r\n    map-underscore-to-camel-case: true\r\n  type-handlers-package: com.huimao.common.mybatisplus\r\n\r\nparking:\r\n  simulator:\r\n    # 模拟器通过 HTTP 对接停车平台开放接口，建议配置为网关地址\r\n    platform-url: http://127.0.0.1:48080/parking\r\n    # 调度线程扫描周期（毫秒）\r\n    schedule-delay-ms: 5000\r\n    # 默认自动心跳间隔（秒）\r\n    default-heartbeat-interval-sec: 30\r\n    # 默认自动回调开闸延迟（秒）\r\n    default-callback-delay-sec: 1\r\n', '4d62f818f3e0d66008c629b1a098b9e0', '2026-04-23 17:48:27', '2026-04-23 17:48:27', NULL, '127.0.0.1', 'I', '', '');
INSERT INTO `his_config_info` VALUES (1, 12, 'application-dev.yml', 'DEFAULT_GROUP', '', 'spring:\n  autoconfigure:\n    exclude: com.alibaba.druid.spring.boot.autoconfigure.DruidDataSourceAutoConfigure\n  mvc:\n    pathmatch:\n      matching-strategy: ant_path_matcher\n# mail配置\n  mail:\n    # 配置 SMTP 服务器地址\n    host: smtpdm.aliyun.com\n    # 发送者邮箱\n    username: xxxxxx@163.com\n    # 配置密码，注意不是真正的密码，而是刚刚申请到的授权码\n    password: xxxxx\n    # 端口号465或587\n    port: 465\n    # 默认的邮件编码为UTF-8\n    default-encoding: UTF-8\n    # 配置SSL 加密工厂\n    properties:\n      mail:\n        smtp:\n          ssl:\n            enable: true\n          socketFactoryClass: javax.net.ssl.SSLSocketFactory\n        #表示开启 DEBUG 模式，这样，邮件发送过程的日志会在控制台打印出来，方便排查错误\n        debug: true\n# feign 配置\nfeign:\n  sentinel:\n    enabled: true\n  okhttp:\n    enabled: true\n  httpclient:\n    enabled: false\n  client:\n    config:\n      default:\n        connectTimeout: 10000\n        readTimeout: 10000\n      huimao-job:\n        connectTimeout: 100000\n        readTimeout: 100000\n  compression:\n    request:\n      enabled: true\n    response:\n      enabled: true\n\n# 暴露监控端点\nmanagement:\n  endpoints:\n    web:\n      exposure:\n        include: \'*\'\nlogging:\n  level:\n    org.springframework: info\n    com.huimao: debug\n  #log日志文件配置\n  file_basePath: ./logs\n  file_prefix: ${spring.application.name}\nmybatis-plus:\n  mapper-locations: classpath*:mapper/**/*.xml\n  global-config:\n    banner: false\n    refresh-mapper: true\n    db-config:\n      id-type: auto\n      table-underline: true\n      logic-delete-value: 1\n      logic-not-delete-value: 0\n  configuration:\n    map-underscore-to-camel-case: true\n  type-handlers-package: com.huimao.common.mybatisplus\nhuimao:                                                                                                                                                                                                                    \n    tenant:                                                                                                                                                                                                                 \n      ignore-tables:                                                                                                                                                                                                        \n        - sys_config                                                                                                                                                                                                        \n        - gen_table                                                                                                                                                                                                         \n        - gen_table_column                                                                                                                                                                                                  \n        - sys_dict_data                                                                                                                                                                                                     \n        - sys_dict_type                                                                                                                                                                                                     \n        - sys_menu                                                                                                                                                                                                          \n        - sys_tenant                                                                                                                                                                                                        \n        - sys_tenant_package                                                                                                                                                                                                \n        - sys_oper_log                                                                                                                                                                                                      \n        - sys_logininfor                                                                                                                                                                                                    \n        - branch_table                                                                                                                                                                                                      \n        - global_table                                                                                                                                                                                                      \n        - lock_table                                                                                                                                                                                                        \n        - undo_log                                                                                                                                                                                                          \n        - xxl_job_group                                                                                                                                                                                                     \n        - xxl_job_info                                                                                                                                                                                                      \n        - xxl_job_lock                                                                                                                                                                                                      \n        - xxl_job_log                                                                                                                                                                                                       \n        - xxl_job_log_report                                                                                                                                                                                                \n        - xxl_job_logglue                                                                                                                                                                                                   \n        - xxl_job_registry                                                                                                                                                                                                  \n        - xxl_job_user                                                                                                                                                                                                      \n        - parking_lot                                                                                                                                                                                                       \n        - parking_gate                                                                                                                                                                                                      \n        - parking_device                                                                                                                                                                                                    \n        - parking_charge_rule                                                                                                                                                                                               \n        - parking_charge_rule_period                                                                                                                                                                                        \n        - parking_tenant_settle_config                                                                                                                                                                                      \n        - parking_session                                                                                                                                                                                                   \n        - parking_order                                                                                                                                                                                                     \n        - parking_payment                                                                                                                                                                                                   \n        - parking_io_event                                                                                                                                                                                                  \n        - parking_gate_command                                                                                                                                                                                              \n        - parking_account                                                                                                                                                                                                   \n        - parking_account_flow                                                                                                                                                                                              \n        - parking_withdraw_order                                                                                                                                                                                            \n        - parking_daily_stat\n      #自定义表\n# 短信服务\naliyun:\n  endpoint: cn-shanghai\n  accessKeyId:  \n  accessKeySecret: \n  signName:  \n  templateCode: \n# 本地文件上传    \nfile:\n  domain: http://127.0.0.1:39300\n  path: /home/upload\n  prefix: /documents\n', '61b2421db2bd8a710d194ff50186b40c', '2026-04-23 17:48:58', '2026-04-23 17:48:58', 'nacos', '127.0.0.1', 'U', '', '');
INSERT INTO `his_config_info` VALUES (2, 13, 'huimao-gateway-dev.yml', 'DEFAULT_GROUP', '', 'spring:\n  redis:\n    host: 127.0.0.1\n    port: 6379\n    password: aq114477\n    timeout: 1000 # 连接超时时间（毫秒）\n    jedis:\n      pool:\n        max-active: 10 # 连接池最大连接数（使用负值表示没有限制）\n        max-wait: -1ms # 连接池最大阻塞等待时间（使用负值表示没有限制）\n        max-idle: 8 # 连接池中的最大  空闲连接\n        min-idle: 0 # 连接池中的最小空闲连接\n  cloud:\n    gateway:\n      discovery:\n        locator:\n          lowerCaseServiceId: true\n          enabled: true\n      routes:\n        # 认证中心\n        - id: huimao-auth\n          uri: lb://huimao-auth\n          predicates:\n            - Path=/auth/**\n          filters:\n            # 验证码处理\n            - CacheRequestFilter\n            - ValidateCodeFilter\n            - StripPrefix=1\n        # 代码生成\n        - id: huimao-gen\n          uri: lb://huimao-gen\n          predicates:\n            - Path=/code/**\n          filters:\n            - StripPrefix=1\n        # 系统模块\n        - id: huimao-system\n          uri: lb://huimao-system\n          predicates:\n            - Path=/system/**\n          filters:\n            - StripPrefix=1\n        # 文件服务\n        - id: huimao-file\n          uri: lb://huimao-file\n          predicates:\n            - Path=/file/**\n          filters:\n            - StripPrefix=1\n        # 监控模块\n        - id: huimao-monitor\n          uri: lb://huimao-monitor\n          predicates:\n            - Path=/monitor/**\n          filters:\n            - StripPrefix=1\n        # 定时模块\n        - id: huimao-job\n          uri: lb://huimao-job\n          predicates:\n            - Path=/job/**\n          filters:\n            - StripPrefix=1\n        # 样例模块\n        - id: huimao-demo\n          uri: lb://huimao-demo\n          predicates:\n            - Path=/demo/**\n          filters:\n            - StripPrefix=1\n        # 停车模块                                                                                                                                                                                                        \n        - id: huimao-parking                                                                                                                                                                                               \n          uri: lb://huimao-parking                                                                                                                                                                                         \n          predicates:                                                                                                                                                                                                     \n            - Path=/parking/**                                                                                                                                                                                            \n          filters:                                                                                                                                                                                                        \n            - StripPrefix=1\n\n# 安全配置\nsecurity:\n  # 验证码\n  captcha:\n    enabled: true\n    type: math\n  # 防止XSS攻击\n  xss:\n    enabled: true\n    excludeUrls:\n      - /system/notice\n  # 不校验白名单\n  ignore:\n    whites:\n      - /auth/logout\n      - /auth/login\n      - /auth/register\n      - /*/v2/api-docs\n      - /csrf\n      - /job/api/callback\n      - /job/api/registry\n      - /job/api/registryRemove\n      - /file/documents/**\n      - /parking/open/device/**                                                                                                                                                                                           \n      - /parking/open/h5/** ', 'e069e4214d6470919afb4c1de24295f8', '2026-04-23 17:49:43', '2026-04-23 17:49:43', 'nacos', '127.0.0.1', 'U', '', '');
INSERT INTO `his_config_info` VALUES (2, 14, 'huimao-gateway-dev.yml', 'DEFAULT_GROUP', '', 'spring:\n  redis:\n    host: 127.0.0.1\n    port: 6379\n    password: aq114477\n    timeout: 1000 # 连接超时时间（毫秒）\n    jedis:\n      pool:\n        max-active: 10 # 连接池最大连接数（使用负值表示没有限制）\n        max-wait: -1ms # 连接池最大阻塞等待时间（使用负值表示没有限制）\n        max-idle: 8 # 连接池中的最大  空闲连接\n        min-idle: 0 # 连接池中的最小空闲连接\n  cloud:\n    gateway:\n      discovery:\n        locator:\n          lowerCaseServiceId: true\n          enabled: true\n      routes:\n        # 认证中心\n        - id: huimao-auth\n          uri: lb://huimao-auth\n          predicates:\n            - Path=/auth/**\n          filters:\n            # 验证码处理\n            - CacheRequestFilter\n            - ValidateCodeFilter\n            - StripPrefix=1\n        # 代码生成\n        - id: huimao-gen\n          uri: lb://huimao-gen\n          predicates:\n            - Path=/code/**\n          filters:\n            - StripPrefix=1\n        # 系统模块\n        - id: huimao-system\n          uri: lb://huimao-system\n          predicates:\n            - Path=/system/**\n          filters:\n            - StripPrefix=1\n        # 文件服务\n        - id: huimao-file\n          uri: lb://huimao-file\n          predicates:\n            - Path=/file/**\n          filters:\n            - StripPrefix=1\n        # 监控模块\n        - id: huimao-monitor\n          uri: lb://huimao-monitor\n          predicates:\n            - Path=/monitor/**\n          filters:\n            - StripPrefix=1\n        # 定时模块\n        - id: huimao-job\n          uri: lb://huimao-job\n          predicates:\n            - Path=/job/**\n          filters:\n            - StripPrefix=1\n        # 样例模块\n        - id: huimao-demo\n          uri: lb://huimao-demo\n          predicates:\n            - Path=/demo/**\n          filters:\n            - StripPrefix=1\n        # 停车模块                                                                                                                                                                                                        \n        - id: huimao-parking                                                                                                                                                                                               \n          uri: lb://huimao-parking                                                                                                                                                                                         \n          predicates:                                                                                                                                                                                                     \n            - Path=/parking/**                                                                                                                                                                                            \n          filters:                                                                                                                                                                                                        \n            - StripPrefix=1\n        - id: huimao-parking-simulator\n          uri: lb://huimao-parking-simulator\n          predicates:\n            - Path=/parking-simulator/**\n          filters:\n            - StripPrefix=1\n\n# 安全配置\nsecurity:\n  # 验证码\n  captcha:\n    enabled: true\n    type: math\n  # 防止XSS攻击\n  xss:\n    enabled: true\n    excludeUrls:\n      - /system/notice\n  # 不校验白名单\n  ignore:\n    whites:\n      - /auth/logout\n      - /auth/login\n      - /auth/register\n      - /*/v2/api-docs\n      - /csrf\n      - /job/api/callback\n      - /job/api/registry\n      - /job/api/registryRemove\n      - /file/documents/**\n      - /parking/open/device/**                                                                                                                                                                                           \n      - /parking/open/h5/** ', 'b6c70d2e975b00e45492e678a033fe70', '2026-04-23 17:50:25', '2026-04-23 17:50:25', 'nacos', '127.0.0.1', 'U', '', '');
INSERT INTO `his_config_info` VALUES (7, 15, 'huimao-file-dev.yml', 'DEFAULT_GROUP', '', '#本地文件服务的配置迁移到公共配置文件里\n# FastDFS配置 -- http://huimao-fastdfs 为hosts映射\nfdfs:\n  domain: http://huimao-fastdfs\n  soTimeout: 3000\n  connectTimeout: 2000\n  trackerList: huimao-fastdfs:22122\n\n# Minio配置\nminio:\n  url: https://huimao-minio\n  accessKey: huimao\n  secretKey: huimao\n  bucketName: huimao', '4b54792f6866e91242030d7102bb81a9', '2026-05-06 09:34:29', '2026-05-06 09:34:30', 'nacos', '127.0.0.1', 'U', '', '');
INSERT INTO `his_config_info` VALUES (18, 16, 'huimao-parking-dev.yml', 'DEFAULT_GROUP', '', '# spring配置\r\nspring:\r\n  redis:\r\n    host: 127.0.0.1\r\n    port: 6379\r\n    password: aq114477\r\n    timeout: 1000\r\n    jedis:\r\n      pool:\r\n        max-active: 10\r\n        max-wait: -1ms\r\n        max-idle: 8\r\n        min-idle: 0\r\n  datasource:\r\n    druid:\r\n      stat-view-servlet:\r\n        enabled: true\r\n        loginUsername: admin\r\n        loginPassword: 123456\r\n    dynamic:\r\n      druid:\r\n        initial-size: 5\r\n        min-idle: 50\r\n        maxActive: 100\r\n        maxWait: 60000\r\n        timeBetweenEvictionRunsMillis: 300000\r\n        minEvictableIdleTimeMillis: 300000\r\n        validationQuery: SELECT 1 FROM DUAL\r\n        testWhileIdle: true\r\n        testOnBorrow: false\r\n        testOnReturn: false\r\n        poolPreparedStatements: true\r\n        maxPoolPreparedStatementPerConnectionSize: 50\r\n        filters: stat,slf4j\r\n        connectionProperties: druid.stat.mergeSql=true;druid.stat.slowSqlMillis=500\r\n      datasource:\r\n        master:\r\n          driver-class-name: com.mysql.cj.jdbc.Driver\r\n          url: jdbc:mysql://127.0.0.1:3306/huimao_platform?useUnicode=true&characterEncoding=utf8&zeroDateTimeBehavior=convertToNull&useSSL=true&serverTimezone=GMT%2B8\r\n          username: root\r\n          password: aq114477\r\n\r\nseata:\r\n  enabled: false\r\n  application-id: ${spring.application.name}\r\n  tx-service-group: ${spring.application.name}-group\r\n  enable-auto-data-source-proxy: false\r\n  service:\r\n    vgroup-mapping:\r\n      huimao-parking-group: default\r\n  config:\r\n    type: nacos\r\n    nacos:\r\n      serverAddr: huimao-nacos:8848\r\n      group: SEATA_GROUP\r\n      namespace:\r\n  registry:\r\n    type: nacos\r\n    nacos:\r\n      application: seata-server\r\n      server-addr: huimao-nacos:8848\r\n      namespace:\r\n\r\nswagger:\r\n  title: 停车场模块接口文档\r\n  license: Powered By huimao\r\n  licenseUrl: https://huimao.vip\r\n\r\nfeign:\r\n  sentinel:\r\n    enabled: true\r\n  okhttp:\r\n    enabled: true\r\n  httpclient:\r\n    enabled: false\r\n  client:\r\n    config:\r\n      default:\r\n        connectTimeout: 10000\r\n        readTimeout: 10000\r\n        loggerLevel: full\r\n        requestInterceptors: com.huimao.common.security.feign.FeignRequestInterceptor\r\n\r\nhuimao:\r\n  tenant:\r\n    ignore-tables:\r\n      - sys_config\r\n      - gen_table\r\n      - gen_table_column\r\n      - sys_dict_data\r\n      - sys_dict_type\r\n      - sys_menu\r\n      - sys_tenant\r\n      - sys_tenant_package\r\n      - sys_oper_log\r\n      - sys_logininfor\r\n      - branch_table\r\n      - global_table\r\n      - lock_table\r\n      - undo_log\r\n      - xxl_job_group\r\n      - xxl_job_info\r\n      - xxl_job_lock\r\n      - xxl_job_log\r\n      - xxl_job_log_report\r\n      - xxl_job_logglue\r\n      - xxl_job_registry\r\n      - xxl_job_user\r\n      - parking_lot\r\n      - parking_gate\r\n      - parking_device\r\n      - parking_charge_rule\r\n      - parking_charge_rule_period\r\n      - parking_tenant_settle_config\r\n      - parking_session\r\n      - parking_order\r\n      - parking_payment\r\n      - parking_io_event\r\n      - parking_gate_command\r\n      - parking_account\r\n      - parking_account_flow\r\n      - parking_withdraw_order\r\n      - parking_daily_stat\r\n', '37eae101f163b4eae42c1e156b94aa39', '2026-05-06 09:38:21', '2026-05-06 09:38:21', 'nacos', '127.0.0.1', 'U', '', '');
INSERT INTO `his_config_info` VALUES (1, 17, 'application-dev.yml', 'DEFAULT_GROUP', '', 'spring:\n  autoconfigure:\n    exclude: com.alibaba.druid.spring.boot.autoconfigure.DruidDataSourceAutoConfigure\n  mvc:\n    pathmatch:\n      matching-strategy: ant_path_matcher\n# mail配置\n  mail:\n    # 配置 SMTP 服务器地址\n    host: smtpdm.aliyun.com\n    # 发送者邮箱\n    username: xxxxxx@163.com\n    # 配置密码，注意不是真正的密码，而是刚刚申请到的授权码\n    password: xxxxx\n    # 端口号465或587\n    port: 465\n    # 默认的邮件编码为UTF-8\n    default-encoding: UTF-8\n    # 配置SSL 加密工厂\n    properties:\n      mail:\n        smtp:\n          ssl:\n            enable: true\n          socketFactoryClass: javax.net.ssl.SSLSocketFactory\n        #表示开启 DEBUG 模式，这样，邮件发送过程的日志会在控制台打印出来，方便排查错误\n        debug: true\n# feign 配置\nfeign:\n  sentinel:\n    enabled: true\n  okhttp:\n    enabled: true\n  httpclient:\n    enabled: false\n  client:\n    config:\n      default:\n        connectTimeout: 10000\n        readTimeout: 10000\n      huimao-job:\n        connectTimeout: 100000\n        readTimeout: 100000\n  compression:\n    request:\n      enabled: true\n    response:\n      enabled: true\n\n# 暴露监控端点\nmanagement:\n  endpoints:\n    web:\n      exposure:\n        include: \'*\'\nlogging:\n  level:\n    org.springframework: info\n    com.huimao: debug\n  #log日志文件配置\n  file_basePath: ./logs\n  file_prefix: ${spring.application.name}\nmybatis-plus:\n  mapper-locations: classpath*:mapper/**/*.xml\n  global-config:\n    banner: false\n    refresh-mapper: true\n    db-config:\n      id-type: auto\n      table-underline: true\n      logic-delete-value: 1\n      logic-not-delete-value: 0\n  configuration:\n    map-underscore-to-camel-case: true\n  type-handlers-package: com.huimao.common.mybatisplus\nhuimao:                                                                                                                                                                                                                    \n    tenant:                                                                                                                                                                                                                 \n      ignore-tables:                                                                                                                                                                                                        \n        - sys_config                                                                                                                                                                                                        \n        - gen_table                                                                                                                                                                                                         \n        - gen_table_column                                                                                                                                                                                                  \n        - sys_dict_data                                                                                                                                                                                                     \n        - sys_dict_type                                                                                                                                                                                                     \n        - sys_menu                                                                                                                                                                                                          \n        - sys_tenant                                                                                                                                                                                                        \n        - sys_tenant_package                                                                                                                                                                                                \n        - sys_oper_log                                                                                                                                                                                                      \n        - sys_logininfor                                                                                                                                                                                                    \n        - branch_table                                                                                                                                                                                                      \n        - global_table                                                                                                                                                                                                      \n        - lock_table                                                                                                                                                                                                        \n        - undo_log                                                                                                                                                                                                          \n        - xxl_job_group                                                                                                                                                                                                     \n        - xxl_job_info                                                                                                                                                                                                      \n        - xxl_job_lock                                                                                                                                                                                                      \n        - xxl_job_log                                                                                                                                                                                                       \n        - xxl_job_log_report                                                                                                                                                                                                \n        - xxl_job_logglue                                                                                                                                                                                                   \n        - xxl_job_registry                                                                                                                                                                                                  \n        - xxl_job_user                                                                                                                                                                                                      \n        - parking_lot                                                                                                                                                                                                       \n        - parking_gate                                                                                                                                                                                                      \n        - parking_device                                                                                                                                                                                                    \n        - parking_charge_rule                                                                                                                                                                                               \n        - parking_charge_rule_period                                                                                                                                                                                        \n        - parking_tenant_settle_config                                                                                                                                                                                      \n        - parking_session                                                                                                                                                                                                   \n        - parking_order                                                                                                                                                                                                     \n        - parking_payment                                                                                                                                                                                                   \n        - parking_io_event                                                                                                                                                                                                  \n        - parking_gate_command                                                                                                                                                                                              \n        - parking_account                                                                                                                                                                                                   \n        - parking_account_flow                                                                                                                                                                                              \n        - parking_withdraw_order                                                                                                                                                                                            \n        - parking_daily_stat\n        - parking_simulator_device\n      #自定义表\n# 短信服务\naliyun:\n  endpoint: cn-shanghai\n  accessKeyId:  \n  accessKeySecret: \n  signName:  \n  templateCode: \n# 本地文件上传    \nfile:\n  domain: http://127.0.0.1:39300\n  path: /home/upload\n  prefix: /documents\n', 'a8435e775156a3ea820345a09cd69fba', '2026-05-06 09:38:57', '2026-05-06 09:38:57', 'nacos', '127.0.0.1', 'U', '', '');
INSERT INTO `his_config_info` VALUES (5, 18, 'huimao-system-dev.yml', 'DEFAULT_GROUP', '', '# spring配置\nspring:\n  redis:\n    host: 127.0.0.1\n    port: 6379\n    password: aq114477\n    timeout: 1000 # 连接超时时间（毫秒）\n    jedis:\n      pool:\n        max-active: 10 # 连接池最大连接数（使用负值表示没有限制）\n        max-wait: -1ms # 连接池最大阻塞等待时间（使用负值表示没有限制）\n        max-idle: 8 # 连接池中的最大  空闲连接\n        min-idle: 0 # 连接池中的最小空闲连接\n  datasource:\n    druid:\n      stat-view-servlet:\n        enabled: true\n        loginUsername: admin\n        loginPassword: 123456\n    dynamic:\n      druid:\n        initial-size: 5\n        min-idle: 50\n        maxActive: 100\n        maxWait: 60000\n        timeBetweenEvictionRunsMillis: 300000\n        minEvictableIdleTimeMillis: 300000\n        validationQuery: SELECT 1 FROM DUAL\n        testWhileIdle: true\n        testOnBorrow: false\n        testOnReturn: false\n        poolPreparedStatements: true\n        maxPoolPreparedStatementPerConnectionSize: 50\n        filters: stat,slf4j\n        connectionProperties: druid.stat.mergeSql=true;druid.stat.slowSqlMillis=500\n      datasource:\n          # 主库数据源\n          master:\n            driver-class-name: com.mysql.cj.jdbc.Driver\n            url: jdbc:mysql://127.0.0.1:3306/huimao_platform?useUnicode=true&characterEncoding=utf8&zeroDateTimeBehavior=convertToNull&useSSL=true&serverTimezone=GMT%2B8\n            username: root\n            password: aq114477\nseata:\n  # 默认关闭，如需启用spring.datasource.dynami.seata需要同时开启\n  enabled: false\n  # Seata 应用编号，默认为 ${spring.application.name}\n  application-id: ${spring.application.name}\n  # Seata 事务组编号，用于 TC 集群名\n  tx-service-group: ${spring.application.name}-group\n  # 关闭自动代理\n  enable-auto-data-source-proxy: false\n  # 服务配置项\n  service:\n    # 虚拟组和分组的映射\n    vgroup-mapping:\n      huimao-system-group: default\n  config:\n    type: nacos\n    nacos:\n      serverAddr: huimao-nacos:8848\n      group: SEATA_GROUP\n      namespace:\n  registry:\n    type: nacos\n    nacos:\n      application: seata-server\n      server-addr: huimao-nacos:8848\n      namespace:\n\n# mybatis配置\n# mybatis:\n#     搜索指定包别名\n#     typeAliasesPackage: com.huimao.system\n#     配置mapper的扫描，找到所有的mapper.xml映射文件\n#     mapperLocations: classpath:mapper/**/*.xml\n\n# swagger配置\nswagger:\n  title: 系统模块接口文档\n  license: Powered By huimao\n  licenseUrl: https://huimao.vip\nfeign:\n  sentinel:\n    enabled: true\n  okhttp:\n    enabled: true\n  httpclient:\n    enabled: false\n  client:\n    config:\n      default:\n        connectTimeout: 10000\n        readTimeout: 10000\n        loggerLevel: full\n        requestInterceptors: com.huimao.common.security.feign.FeignRequestInterceptor\n', '1fdb5989bb61ae7912e2beb2568970d1', '2026-05-06 09:41:50', '2026-05-06 09:41:51', 'nacos', '127.0.0.1', 'U', '', '');
