                           \n        - sys_menu                                                                                                                                                                                                          \n        - sys_tenant                                                                                                                                                                                                        \n        - sys_tenant_package                                                                                                                                                                                                \n        - sys_oper_log                                                                                                                                                                                                      \n        - sys_logininfor                                                                                                                                                                                                    \n        - branch_table                                                                                                                                                                                                      \n        - global_table                                                                                                                                                                                                      \n        - lock_table                                                                                                                                                                                                        \n        - undo_log                                                                                                                                                                                 